/* ----- round 12: eight scenes about Fun › On the tour (ids gd12_*; research 5.1 and 5.3's "tests the developer can press"): a promised
   quiz all right; two wrong, Show me; a stop, then the quiz from the ✦; a skipped step gives no question; too few questions, no promise;
   Expert's opt-in; the breather; guess the year. Each keeps what it changes (the guidance, the questions, the guesses, the audience, the
   introduction, Liveliness) and gives it back after; the tour runs with its own voice, and where a scene needs a later seam it moves the
   tour there (the steps between counted as heard, said in its question). Only Fun › On the tour is On ----- */
function gd12Keep(){G.gd.sc12={g:JSON.parse(JSON.stringify(S.guidance)),q:JSON.parse(JSON.stringify(S.tourQ)),gs:JSON.parse(JSON.stringify(S.tourGuess)),aud:S.vis.aud,len:S.vis.len,intro:S.introSeen,life:S.guideCfg.life,solemn:S.m.solemn,look:S.guideCfg.look};
  if(G.on)stopTour();gdBeatClose();G.cam={open:false,answer:"",busy:false,lit:[],route:[],hunt:null};S.settingsOpen=false;G.fab.menu=false;S.view="card";S.stop="full";renderPhone(false)}
function gd12Done(r){var k=G.gd.sc12;if(k){gdStop("the scene ended");if(G.on)stopTour();gdBeatClose();G.gd.owed=null;S.guidance=k.g;S.tourQ=k.q;S.tourGuess=k.gs;S.vis.aud=k.aud;S.vis.len=k.len;S.introSeen=k.intro;S.guideCfg.life=k.life;S.m.solemn=k.solemn;G.gd.sc12=null;S.view="card";S.stop="full";renderPhone(false)}return gdScDone(r)}
/* the scene's start: a first visit, only Fun › On the tour On, Lively, no introduction (the tour starts at its welcome) */
function gd12Only(ids){gdScSetup(10,true,"fun");S.guidance.kinds.forEach(function(k){k.on=k.id==="fun"});gdGroupById("play").on=false;gdGroupById("ontour").on=true;
  ["quizpromise","quizfinale","guessyear","water","cookie"].forEach(function(id){S.guidance.items[id].on=ids.indexOf(id)>=0});S.guideCfg.life="lively";S.m.solemn=false;S.introSeen=true;S.vis.aud="explorer";S.vis.len="";S.view="card";S.stop="full";renderPhone(false)}
/* the tour moved to a step's seam (the steps up to it heard), and on: the beat planned there plays */
function gd12Seam(id){var j=S.guideSteps.findIndex(function(s){return s.id===id});if(j<0||!G.on)return false;stopSpeech();clearTimeout(G.timer);G.timer=null;G.waiting=false;G.paused=false;G.i=j;
  S.guideSteps.slice(0,j+1).forEach(function(s){G.gd.heard[s.id]=1});renderGuide();next();return true}
function gd12Kind(k){return!!(G.gd.bt&&G.gd.bt.kind===k&&ph.querySelector(".gdbeat"))}
/* round 13: the quiz's seam is the plan's (with the quiz promised the card's own quiz step is skipped: the seam after the step before it) */
function gd12Fin(){var b=gdPlanBeat("quizfinale");return b?b.after:"g9"}
function gd12Tap(sel){var e=ph.querySelector(".gdbeat "+sel)||ph.querySelector(sel);return e?gsTouch(e):false}
/* each question answered by a tap (right: its right one; a list of choices: wrong ones), Next tapped after each verdict */
function gd12Answer(pick){var B=G.gd.bt;if(!B||B.kind!=="finale"||B.answered!=null)return false;var q=gdQuizQ(B,B.k),ok=+q.ok,i=pick==="right"?ok:pick==="wrong"?(ok+1)%q.a.length:pick;return gd12Tap('[data-gdbt="ans"][data-i="'+i+'"]')}
function gd12Quiz(picks,from){var k0=from||0,k=k0;return new Promise(function(res){(function step(){if(k-k0>=picks.length){res(true);return}
  gdScWait(function(){var B=G.gd.bt;return B&&B.kind==="finale"&&B.answered==null&&B.k===k&&!!ph.querySelector(".gdbeat .bt-choice")},20000).then(function(ok){if(!ok){res(false);return}gd12Answer(picks[k-k0]);
    gdScWait(function(){return!!ph.querySelector(".gdbeat .bt-verdict")},4000).then(function(){setTimeout(function(){k++;gd12Tap('[data-gdbt="next"]');step()},600)})})})()})}
function gd12Over(){var obs=propObstacles(),a=G.propAt;if(!a)return-1;return obs.reduce(function(s,b){return s+Math.max(0,Math.min(b.r,a.x+PROP)-Math.max(b.l,a.x))*Math.max(0,Math.min(b.b,a.y+PROP)-Math.max(b.t,a.y))},0)}
